   // 5. Check return code\n            if (httpCode > 0) {\n                Serial.printf("[HTTPS] GET... code: %d\\n", httpCode);\n\n                if (httpCode == HTTP_CODE_OK || httpCode == 301 || httpCode == 302) {\n                    String payload = http.getString();\n                    Serial.println(payload);\n                }\n            } else {\n                Serial.printf("[HTTPS] GET... failed, error: %s\\n", http.errorToString(httpCode).c_str());\n            }\n\n            // 6. Close connection\n            http.end();\n        } else {\n            Serial.printf("[HTTPS] Unable to connect\\n");\n        }\n    }\n\n    delay(10000);\n}\n'})}),"\n",(0,l.jsx)(e.h4,{id:"\u6548\u679C\u5C55\u793A-4",children:"\u6548\u679C\u5C55\u793A"}),"\n",(0,l.jsx)(e.admonition,{type:"tip",children:(0,l.jsxs)(e.p,{children:[(0,l.jsx)(e.code,{children:"https://jsonplaceholder.typicode.com"})," \u662F\u4E00\u4E2A\u514D\u8D39\u7684\u6A21\u62DF REST API \u6D4B\u8BD5\u670D\u52A1\uFF0C\u4E13\u4E3A\u5F00\u53D1\u548C\u6D4B\u8BD5\u76EE\u7684\u800C\u8BBE\u8BA1\u3002\u5B83\u4E0D\u652F\u6301\u5BF9\u771F\u5B9E\u6570\u636E\u8FDB\u884C\u6C38\u4E45\u4FEE\u6539\u6216\u6301\u4E45\u5316\u3002"]})}),"\n",(0,l.jsxs)(e.ul,{children:["\n",(0,l.jsxs)(e.li,{children:["\u4E0A\u4F20\u4EE3\u7801\uFF0C\u7136\u540E\u4F60\u53EF\u4EE5\u6253\u5F00 ",(0,l.jsx)(e.code,{children:"https://jsonplaceholder.typicode.com/todos/1"})," \u548C Arduino IDE \u4E2D\u7684\u4E32\u53E3\u76D1\u89C6\u5668\u5DE5\u5177\uFF0C\u68C0\u67E5\u4FE1\u606F\u662F\u5426\u4E00\u81F4\u3002"]}),"\n"]}),"\n",(0,l.jsx)("div",{style:{textAlign:"center"},children:(0,l.jsx)("img",{src:"https://files.seeedstudio.com/wiki/XIAO_ESP32C5/Getting_started/wifi_usage_9.png",style:{width:800,height:"auto"}})}),"\n",(0,l.jsx)(e.h3,{id:"wifi-mesh",children:"WiFi-Mesh"}),"\n",(0,l.jsxs)(e.p,{children:["\u4EE5\u4E0B\u662F\u4E50\u946B\u5B98\u65B9\u5BF9 ",(0,l.jsx)(e.strong,{children:"ESP-WIFI-MESH"})," \u7684\u4ECB\u7ECD\uFF1A"]}),"\n",(0,l.j